const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '!dataset/**' -g '!node_modules/**' /app /tmp 2>/dev/null | head -80", max_output_tokens:3000}),
  tools.exec_command({cmd:"ls -lh /app/dataset && head -12 /app/dataset/farms.csv && head -12 /app/dataset/farm_registry.csv && cat /app/dataset/sensors_calibration.json && cat /app/dataset/maintenance_notes.txt", max_output_tokens:15000})
]); for (let i=0;i<results.length;i++) text({index:i,...results[i]});

